import{_ as d,C as n,o as s,c as r,j as o,a,E as c,a2 as i}from"./chunks/framework.Di-jvWLj.js";const x=JSON.parse('{"title":"Docker Image","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/docker.md","filePath":"deployment/docker.md","lastUpdated":1792917162000}'),l={name:"deployment/docker.md"},h={id:"docker-image",tabindex:"-1"};function g(m,e,u,p,b,f){const t=n("Badge");return s(),r("div",null,[o("h1",h,[e[0]||(e[0]=a("Docker Image ",-1)),c(t,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#docker-image","aria-label":'Permalink to "Docker Image <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=i('<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The template repository does not exist yet. The <a href="#base-image">base image</a>, the <a href="/reference/cli#build-output"><code>chamvi build</code></a> command and the <a href="#sandbox-image">sandbox image</a> do.</p></div><h2 id="base-image" tabindex="-1">Base image <a class="header-anchor" href="#base-image" aria-label="Permalink to &quot;Base image&quot;">​</a></h2><p>Agent images build their runtime stage on <code>ghcr.io/chamvi/node</code>, built from <a href="https://github.com/chamvi/chamvi/tree/master/images/node" target="_blank" rel="noreferrer"><code>images/node</code></a>.</p><ul><li><strong>Contents:</strong> <code>node:24-trixie-slim</code> (Node.js 24, npm, corepack), ca-certificates, <code>tini</code> as the entrypoint (signals reach Node, orphaned processes are reaped), <code>NODE_ENV=production</code>, <code>WORKDIR /app</code> owned by root (the app reads its code, never writes it), <code>USER 1000:1000</code> (numeric, so Kubernetes <code>runAsNonRoot</code> can verify it); the default command is <code>node</code>. The shell stays for <code>kubectl exec</code>. No git and no compiler: build native addons in a <code>node:24-trixie-slim</code> build stage (same Debian 13 glibc).</li><li><strong>Platforms:</strong> <code>linux/amd64</code> and <code>linux/arm64</code>.</li><li><strong>Tags:</strong> <code>24</code>, rebuilt on every push to <code>master</code> that changes anything under <code>images/</code> (or the workflow), weekly for base image security updates and on manual runs, and <code>24-&lt;short sha&gt;</code>, one tag per such push to <code>master</code> (the weekly and manual rebuilds move only <code>24</code>). Pull requests that touch the image build and smoke-test it without pushing.</li><li><strong>Pinning:</strong> reference a digest in production (<code>FROM ghcr.io/chamvi/node:24@sha256:...</code>).</li><li><strong>Workspaces:</strong> without git the image cannot host <code>@chamvi/sandbox-local</code> workspaces; in a cluster, run them with <code>@chamvi/sandbox-k8s</code> and the <a href="#sandbox-image">sandbox image</a>.</li></ul><h2 id="agent-images" tabindex="-1">Agent images <a class="header-anchor" href="#agent-images" aria-label="Permalink to &quot;Agent images&quot;">​</a></h2><p>Agent repositories use a two-stage Dockerfile from the template:</p><ol><li><strong>Build stage:</strong> install dependencies and bundle the app entry with <code>chamvi build</code>.</li><li><strong>Runtime stage:</strong> copy the bundle onto the base image and start it with an exec-form <code>CMD</code>, so <code>SIGTERM</code> reaches Node (forwarded by the base image&#39;s tini) and the engine can <a href="/guide/recovery#drain">drain</a>.</li></ol><p>The same image serves every mode: the long-running app, and a one-shot <code>chamvi run-job &lt;agent&gt; [subscriptionId]</code> (the agent&#39;s only cron subscription by default) for clusters that prefer Kubernetes CronJobs over in-process scheduling.</p><h2 id="tags-for-flux" tabindex="-1">Tags for Flux <a class="header-anchor" href="#tags-for-flux" aria-label="Permalink to &quot;Tags for Flux&quot;">​</a></h2><p>The template&#39;s CI pushes images tagged <code>main-&lt;sha&gt;-&lt;unix timestamp&gt;</code> for every push to the main branch, plus semver tags for releases. Flux image automation picks the newest tag and updates the <code>HelmRelease</code>. See <a href="/deployment/kubernetes">Kubernetes &amp; Flux</a>.</p><h2 id="sandbox-image" tabindex="-1">Sandbox image <a class="header-anchor" href="#sandbox-image" aria-label="Permalink to &quot;Sandbox image&quot;">​</a></h2><p>Agents that run untrusted code (reproducing a bug, running tests) do it in <a href="/guide/workspaces">workspaces</a> from a separate image, <code>ghcr.io/chamvi/sandbox-node</code>, built from <a href="https://github.com/chamvi/chamvi/tree/master/images/sandbox-node" target="_blank" rel="noreferrer"><code>images/sandbox-node</code></a>. It runs as its own container (<code>@chamvi/sandbox-docker</code>) or pod (<code>@chamvi/sandbox-k8s</code>), never inside the agent&#39;s container.</p><ul><li><strong>Contents:</strong> <code>node:24-trixie-slim</code> (Node.js 24, npm, corepack), git, ca-certificates, <code>tini</code> as the entrypoint, GNU coreutils <code>timeout</code>; <code>/workspace</code> owned by uid 1000, <code>USER 1000:1000</code>. npm&#39;s cache, global prefix and corepack live under <code>/tmp</code>, so everything works on the read-only root filesystem the providers enforce.</li><li><strong>Platforms:</strong> <code>linux/amd64</code> and <code>linux/arm64</code>.</li><li><strong>Tags:</strong> <code>24</code>, rebuilt on every change under <code>images/</code> on <code>master</code> and weekly for base image security updates, and <code>24-&lt;short sha&gt;</code>, one tag per push to <code>master</code> that changes the image (the weekly rebuild moves only <code>24</code>). Pull requests that touch the image build and smoke-test it without pushing.</li><li><strong>Pinning:</strong> reference a digest in production (<code>ghcr.io/chamvi/sandbox-node@sha256:...</code>), or follow the mutable <code>24</code> tag with <code>pull: &#39;always&#39;</code> (Docker) or <code>imagePullPolicy: &#39;Always&#39;</code> (Kubernetes).</li><li><strong>Extending:</strong> build <code>FROM ghcr.io/chamvi/sandbox-node:24</code>, install packages as root, switch back to <code>USER 1000:1000</code> and pass the image as <code>image</code> to the provider. The providers need <code>sh</code>, <code>cat</code>, <code>head</code>, <code>mkdir</code>, <code>dirname</code>, <code>cp</code>, <code>mv</code>, <code>rm</code>, GNU <code>timeout</code> and <code>git</code>.</li></ul><p>On a Docker host, the agent needs access to the Docker API to start sandbox containers. That access is root on the host: give the agent a socket proxy that allows only containers, exec and images, or run rootless Docker. See <a href="/reference/sandbox#chamvi-sandbox-docker"><code>@chamvi/sandbox-docker</code></a>.</p>',14))])}const v=d(l,[["render",g]]);export{x as __pageData,v as default};
